  function dashboard() { const recent = state.orders.slice(-6).reverse(); const sold = {}; state.orders.filter(o => o.status !== "Annulée" && o.status !== "Remboursée").forEach(o => o.items.forEach(i => sold[i.name] = (sold[i.name] || 0) + i.qty)); const best = Object.entries(sold).sort((a, b) => b[1] - a[1]).slice(0, 5); return `<div class="grid cards"><div class="card"><span class="label">${t("revenue")}</span><strong>${money(revenue())}</strong><span class="muted">${t("all")}</span></div><div class="card"><span class="label">${t("ordersCount")}</span><strong>${state.orders.filter(o => o.status !== "Annulée" && o.status !== "Remboursée").length}</strong><span class="muted">${t("all")}</span></div><div class="card"><span class="label">${t("expensesTotal")}</span><strong>${money(expensesTotal())}</strong><span class="muted">${t("all")}</span></div><div class="card"><span class="label">${t("profit")}</span><strong>${money(profit())}</strong><span class="muted">${t("all")}</span></div></div><div class="grid two" style="margin-top:18px"><div class="panel"><h2>${t("sevenDays")}</h2>${chart()}</div><div class="panel"><h2>${t("bestSales")}</h2>${best.length ? table(best.map(x => [esc(x[0]), `${x[1]}`]), [t("products"), t("quantityField")]) : `<div class="empty">${t("noSales")}</div>`}</div></div><div class="panel" style="margin-top:18px"><h2>${t("recentOrders")}</h2>${table(recent.map(o => [new Date(o.date).toLocaleDateString(language === "ar" ? "ar-DZ" : "fr-DZ"), o.items.map(i => `${esc(i.name)} ×${i.qty}`).join(", "), money(o.total), `<span class="tag ${o.status === "Annulée" ? "red" : ""}">${o.status}</span>`]), [t("date"), t("itemField"), t("total"), t("status")])}</div>`; }
