  function categories() { return `<div class="panel"><div class="actions"><div><h2>${t("categories")}</h2><p class="muted">${t("premium")}</p></div><button class="btn primary" id="add-category">＋ ${t("add")}</button></div>${table(state.categories.map(c => [`<div class="thumb">${c.image ? `<img src="${c.image}" alt="">` : t("noImage")}</div>`, `<strong>${esc(c.name)}</strong>`, state.products.filter(p => p.category === c.name).length, `<button class="btn" data-edit-category="${c.id}">${t("edit")}</button> <button class="btn danger" data-delete-category="${c.id}">${t("delete")}</button>`]), [t("categoryImage"), t("categories"), t("categoryProducts"), t("actions")])}</div>`; }
