  function stock() { const low = state.products.filter(p => Number(p.stock) <= Number(p.minStock)); return `<div class="grid cards"><div class="card"><span class="label">${t("trackedItems")}</span><strong>${state.products.length}</strong></div><div class="card"><span class="label">${t("alerts")}</span><strong>${low.length}</strong></div></div><div class="panel" style="margin-top:18px"><div class="actions"><div><h2>${t("stock")}</h2><p class="muted">${t("premium")}</p></div><button class="btn primary" id="add-stock">＋ ${t("add")}</button></div>${table(state.products.map(p => [esc(p.name), p.stock ?? 0, p.minStock ?? 5, p.stock <= p.minStock ? `<span class="tag red">${t("lowStock")}</span>` : `<span class="tag">${t("availableStock")}</span>`]), [t("productField"), t("quantityField"), t("minField"), t("status")])}</div>`; }
