  function reports() { return `<div class="grid cards"><div class="card"><span class="label">${t("revenue")}</span><strong>${money(revenue())}</strong></div><div class="card"><span class="label">${t("cost")}</span><strong>${money(costs())}</strong></div><div class="card"><span class="label">${t("expensesTotal")}</span><strong>${money(expensesTotal())}</strong></div><div class="card"><span class="label">${t("profit")}</span><strong>${money(profit())}</strong></div></div><div class="panel" style="margin-top:18px"><div class="actions"><h2>${t("salesReport")}</h2><button class="btn" id="export-report">${t("exportCsv")}</button></div>${table(state.orders.map(o => [new Date(o.date).toLocaleDateString(language === "ar" ? "ar-DZ" : "fr-DZ"), o.items.length, money(o.total), money(o.items.reduce((a, i) => a + i.cost * i.qty, 0)), o.status]), [t("date"), t("itemField"), t("revenue"), t("cost"), t("status")])}</div>`; }
