    document.querySelectorAll("[data-delete-product]").forEach(x => x.onclick = () => confirmModal(t("confirmDeleteProduct"), t("productHistorical"), () => { state.products = state.products.filter(p => p.id !== x.dataset.deleteProduct); safeSave(() => { render(); toast(t("productDeleted")); }); }));
    const filterProducts = () => { const q = (document.getElementById("product-search")?.value || "").toLowerCase(), c = document.getElementById("product-filter")?.value || ""; document.getElementById("product-table").innerHTML = table(state.products.filter(p => p.name.toLowerCase().includes(q) && (!c || p.category === c)).map(p => productRows().find((_, i) => state.products[i].id === p.id) || []), [t("productImage"), t("products"), t("category"), t("price"), t("cost"), t("availability"), t("actions")]); bindProductActions(); };
    document.getElementById("product-search")?.addEventListener("input", filterProducts); document.getElementById("product-filter")?.addEventListener("change", filterProducts); bindProductActions();
    document.getElementById("add-category")?.addEventListener("click", () => categoryModal());
