    document.querySelectorAll("[data-delete-category]").forEach(x => x.onclick = () => { const c = state.categories.find(y => y.id === x.dataset.deleteCategory); if (!c) return; if (state.products.some(p => p.category === c.name)) return confirmModal(t("confirmDeleteCategory"), t("categoryUsed"), () => deleteCategory(c)); confirmModal(t("confirmDeleteCategory"), t("categoryUsed"), () => deleteCategory(c)); });
    document.getElementById("add-stock")?.addEventListener("click", stockModal);
    document.getElementById("add-expense")?.addEventListener("click", () => expenseModal());
    document.querySelectorAll("[data-edit-expense]").forEach(x => x.onclick = () => expenseModal(state.expenses.find(e => e.id === x.dataset.editExpense)));
    document.querySelectorAll("[data-delete-expense]").forEach(x => x.onclick = () => confirmModal(t("confirmDeleteExpense"), t("expenseRemoved"), () => { state.expenses = state.expenses.filter(e => e.id !== x.dataset.deleteExpense); safeSave(() => { render(); toast(t("expenseDeleted")); }); }));
    document.getElementById("expense-date")?.addEventListener("change", e => document.getElementById("expense-table").innerHTML = expenseTable(e.target.value));
    document.getElementById("clear-expense-filter")?.addEventListener("click", () => { document.getElementById("expense-date").value = ""; document.getElementById("expense-table").innerHTML = expenseTable(""); });
    document.getElementById("order-filter")?.addEventListener("change", e => document.getElementById("orders-table").innerHTML = ordersTable(e.target.value));
    document.querySelectorAll("[data-print]").forEach(x => x.onclick = () => printOrder(state.orders.find(o => o.id === x.dataset.print)));
    document.querySelectorAll("[data-cancel]").forEach(x => x.onclick = () => confirmModal(t("confirmCancelOrder"), t("stockRestored"), () => cancelOrder(x.dataset.cancel)));
