  function confirmModal(title, message, action) { openModal(title, `<p class="modal-message">${message}</p>`, async () => { action(); }, t("confirm")); }
  function ticketLogo() { return state.settings.logo ? `<img class="ticket-logo" src="${esc(state.settings.logo)}" alt="Logo">` : `<div class="ticket-logo-placeholder">✦</div>`; }


