  function importData(e) { const file = e.target.files[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const incoming = JSON.parse(reader.result); if (!incoming.products || !incoming.orders || !incoming.categories) throw new Error(); confirmModal(t("confirmImport"), t("replaceCurrent"), () => { state = migrate(incoming); safeSave(() => { layout(); toast(t("imported")); }); }); } catch { fail(t("invalidBackupFile")); } }; reader.readAsText(file); e.target.value = ""; }
  function exportReport() { const rows = [["Date", "Articles", "Ventes", "Coût", "État"], ...state.orders.map(o => [new Date(o.date).toLocaleDateString(language === "ar" ? "ar-DZ" : "fr-DZ"), o.items.length, o.total, o.items.reduce((a, i) => a + i.cost * i.qty, 0), o.status])]; const csv = rows.map(r => r.map(v => `"${String(v).replace(/"/g, '""')}"`).join(",")).join("\n"), a = document.createElement("a"); a.href = URL.createObjectURL(new Blob(["\ufeff" + csv], { type: "text/csv" })); a.download = `rapport-dz-legends-${today()}.csv`; a.click(); }
  function modalShell(title, body, submitLabel = t("save")) { return `<div class="modal-backdrop" id="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" type="button" data-close-modal>×</button></div><form id="modal-form"><div class="modal-body">${body}</div><div class="modal-actions"><button class="btn" type="button" data-close-modal>${t("cancel")}</button><button class="btn primary" type="submit">${submitLabel}</button></div></form></section></div>`; }
  function openModal(title, body, onSubmit, submitLabel = t("save")) { closeModal(); document.body.insertAdjacentHTML("beforeend", modalShell(title, body, submitLabel)); modal = document.getElementById("modal-backdrop"); modal.querySelectorAll("[data-close-modal]").forEach(b => b.onclick = closeModal); modal.onclick = e => { if (e.target === modal) closeModal(); }; const form = modal.querySelector("#modal-form"), image = form.querySelector("[name=image]"); if (image) image.onchange = async () => { const data = await readImage(image), preview = form.querySelector("#image-preview"); if (data === false) { preview.textContent = t("invalidImage"); return; } if (data) preview.innerHTML = `<img src="${data}" alt="${t("imagePreview")}">`; }; form.onsubmit = async e => { e.preventDefault(); const result = await onSubmit(new FormData(form), form); if (result !== false) closeModal(); }; setTimeout(() => modal.querySelector("input,select,textarea")?.focus(), 20); }
