  function readImage(input) { return new Promise(resolve => { const file = input?.files?.[0]; if (!file) return resolve(null); if (!/^image\/(png|jpeg|webp)$/.test(file.type) || file.size > 5 * 1024 * 1024) return resolve(false); const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.readAsDataURL(file); }); }
  function productModal(product = null) { const p = product || { name: "", category: state.categories[0]?.name || "", price: "", cost: "", description: "", available: true, image: "", stock: 0, minStock: 5 }; openModal(product ? t("editProduct") : t("newProduct"), `<div class="form-row"><div class="field"><label>${t("name")} *</label><input name="name" required maxlength="80" value="${esc(p.name)}"></div><div class="field"><label>${t("category")} *</label><select name="category" required>${state.categories.map(c => `<option ${c.name === p.category ? "selected" : ""}>${esc(c.name)}</option>`).join("")}<option value="${t("noCategory")}" ${!p.category ? "selected" : ""}>${t("noCategory")}</option></select></div></div><div class="form-row"><div class="field"><label>${t("price")} (DA) *</label><input name="price" type="number" min="0" step="1" required value="${p.price}"></div><div class="field"><label>${t("cost")} (DA)</label><input name="cost" type="number" min="0" step="1" value="${p.cost || 0}"></div></div><div class="field"><label>${t("description")}</label><textarea name="description" rows="3" maxlength="300">${esc(p.description)}</textarea></div><div class="form-row"><div class="field"><label>${t("initialStock")}</label><input name="stock" type="number" min="0" step="1" value="${p.stock || 0}"></div><div class="field"><label>${t("minStock")}</label><input name="minStock" type="number" min="0" step="1" value="${p.minStock ?? 5}"></div></div><label class="check"><input name="available" type="checkbox" ${p.available !== false ? "checked" : ""}> ${t("available")}</label>${imageField(p.image)}`, async (fd, form) => { const name = String(fd.get("name") || "").trim(), price = Number(fd.get("price")), cost = Number(fd.get("cost") || 0); if (!name) return formError(form, t("required")); if (!Number.isFinite(price) || price < 0) return formError(form, t("invalid")); if (!Number.isFinite(cost) || cost < 0) return formError(form, t("invalid")); const image = await readImage(form.querySelector("[name=image]")); if (image === false) return formError(form, t("invalidImage")); const item = { ...p, id: p.id || uid(), name, category: String(fd.get("category")), price, cost, description: String(fd.get("description") || "").trim(), stock: Math.max(0, Number(fd.get("stock") || 0)), minStock: Math.max(0, Number(fd.get("minStock") || 0)), available: fd.get("available") === "on", image: fd.get("removeImage") === "on" ? "" : image || p.image || "" }; if (!p.id) state.products.push(item); else Object.assign(state.products.find(x => x.id === p.id), item); safeSave(() => { render(); toast(p.id ? t("productModified") : t("productAdded")); }); }); }
