  function expenseModal(expense = null) { const x = expense || { label: "", amount: "", date: today() }; openModal(expense ? t("editExpense") : t("newExpense"), `<div class="form-row"><div class="field"><label>${t("label")} *</label><input name="label" required value="${esc(x.label)}"></div><div class="field"><label>${t("amount")} (DA) *</label><input name="amount" required type="number" min="0" step="1" value="${x.amount}"></div></div><div class="field"><label>${t("date")}</label><input name="date" type="date" value="${x.date?.slice(0, 10) || today()}"></div>`, async (fd, form) => { const amount = Number(fd.get("amount")); if (!String(fd.get("label") || "").trim() || !Number.isFinite(amount) || amount < 0) return formError(form, t("invalid")); const item = { ...x, id: x.id || uid(), label: String(fd.get("label")).trim(), amount, date: new Date(`${fd.get("date")}T12:00:00`).toISOString() }; if (!x.id) state.expenses.push(item); else Object.assign(state.expenses.find(e => e.id === x.id), item); safeSave(() => { render(); toast(t("expenseSaved")); }); }); }
  function stockModal() { if (!state.products.length) return fail(t("noProductFirst")); openModal(t("stockMovement"), `<div class="field"><label>${t("productField")} *</label><select name="product">${state.products.map(p => `<option value="${p.id}">${esc(p.name)} — ${p.stock || 0}</option>`).join("")}</select></div><div class="form-row"><div class="field"><label>${t("typeField")}</label><select name="type"><option value="in">${t("entryField")}</option><option value="out">${t("exitField")}</option></select></div><div class="field"><label>${t("quantityField")} *</label><input name="quantity" type="number" min="1" step="1" required></div></div><div class="field"><label>${t("noteField")}</label><input name="note" maxlength="120" placeholder="${t("noteField")}"></div>`, async (fd, form) => { const q = Number(fd.get("quantity")), p = state.products.find(x => x.id === fd.get("product")); if (!p || !Number.isInteger(q) || q < 1) return formError(form, t("invalid")); if (fd.get("type") === "out" && q > p.stock) return formError(form, t("invalid")); p.stock += fd.get("type") === "in" ? q : -q; state.stockMovements.push({ id: uid(), productId: p.id, type: fd.get("type"), quantity: q, note: String(fd.get("note") || ""), date: new Date().toISOString() }); safeSave(() => { render(); toast(t("stockUpdated")); }); }); }
