  window.addEventListener("hashchange", () => { if (!currentUser) return showLogin(t("invalidCredentials")); const requested = routePage(); if (requested) { page = requested; layout(); } else { location.hash = `#/${page}`; } });
  load().then(async s => { state = s; const remote = await syncFromServer(); if (remote) state = migrate(state); await ensureCircularFavicon(); setFavicon(state.settings.favicon64 || state.settings.logo); await protectLegacyPasswords(); currentUser = sessionUser(); if (!currentUser) return setupNeeded() ? showSetup() : showLogin(); page = routePage() || "dashboard"; layout(); if (REMOTE_SYNC) setInterval(async () => { if (currentUser) { const changed = await syncFromServer(); if (changed) layout(); } }, 15000); }).catch((e) => { console.error("LOAD FAILED:", e); document.getElementById("app").innerHTML = `<main class="main"><div class="panel"><h1>${t("storageUnavailable")}</h1><p>${e && e.message ? e.message : t("browserBlocks")}</p></div></main>`; });
